    previous: HISTORY.slice(-2 * range, -range),
  };
}

export function totals(rows: DayRow[]): Totals {
  let sessions = 0;
  let orders = 0;
  let revenue = 0;
  for (const r of rows) {
    sessions += r.sessions;
    orders += r.orders.reduce((a, b) => a + b, 0);
