        <span className={`kpi-delta kpi-${dir}`}>
          <span aria-hidden="true">{arrow}</span> {fmtDelta(delta)}
        </span>
        <span className="kpi-vs">к предыдущим {range} дн.</span>
      </div>
      <Sparkline values={spark} />
    </div>
  );
