    render: ({ range, current }, view) => {
      const parts: Part[] = trafficSources(range, totals(current)).map((s, idx) => ({
        name: s.name,
        share: s.share,
        valueFull: `${fmtInt(s.value)} · ${fmtShare(s.share)}`,
        color: `var(--s${idx + 1})`,
