    saveLayout(layout);
  }, [layout]);

  const data: DashboardData = useMemo(() => {
    const { current, previous } = sliceRange(range);
    return { range, current, previous };
  }, [range]);

  const items = preview ?? layout;
  const colW = colWidthPx(gridSize.width);
  const gridHeight = gridHeightPx(items);

  const beginDrag = (e: PointerEvent<HTMLButtonElement>, id: string, mode: DragState['mode']) => {
    if (!editing) return;
    e.preventDefault();
    e.currentTarget.setPointerCapture(e.pointerId);
    const origin = layout.find((it) => it.i === id);
    if (!origin) return;
    drag.current = {
      id,
      mode,
      pointerId: e.pointerId,
      startX: e.clientX,
      startY: e.clientY,
      base: layout,
      origin,
      latest: layout,
    };
    setActiveId(id);
  };

  const onDragMove = (e: PointerEvent<HTMLButtonElement>) => {
    const d = drag.current;
    if (!d || e.pointerId !== d.pointerId) return;
    const stepX = colW + GAP;
    const stepY = ROW_H + GAP;
    if (stepX <= 0) return;
    const dx = Math.round((e.clientX - d.startX) / stepX);
    const dy = Math.round((e.clientY - d.startY) / stepY);
    const patch =
      d.mode === 'move'
        ? { x: d.origin.x + dx, y: d.origin.y + dy }
        : { w: d.origin.w + dx, h: d.origin.h + dy };
    const next = updateItem(d.base, d.id, patch, sizeOfWidget);
    if (!sameLayout(next, d.latest)) {
      d.latest = next;
      setPreview(next);
    }
  };

  const endDrag = (e: PointerEvent<HTMLButtonElement>, commit: boolean) => {
    const d = drag.current;
    if (!d || e.pointerId !== d.pointerId) return;
    drag.current = null;
    if (commit && !sameLayout(d.latest, layout)) {
      setLayout(d.latest);
    }
    setPreview(null);
    setActiveId(null);
  };

  const onHandleKey = (e: KeyboardEvent<HTMLButtonElement>, id: string, mode: DragState['mode']) => {
    const delta = ARROW_DELTA[e.key];
    if (!delta) return;
    e.preventDefault();
    const it = layout.find((x) => x.i === id);
    if (!it) return;
    const [dx, dy] = delta;
    const patch = mode === 'move' ? { x: it.x + dx, y: it.y + dy } : { w: it.w + dx, h: it.h + dy };
    const next = updateItem(layout, id, patch, sizeOfWidget);
    if (sameLayout(next, layout)) return;
    setLayout(next);
    const moved = next.find((x) => x.i === id);
    const title = WIDGETS.find((w) => w.id === id)?.title ?? id;
    if (moved) {
      setAnnounce(
        mode === 'move'
          ? `${title}: колонка ${moved.x + 1}, строка ${moved.y + 1}`
          : `${title}: ${moved.w} колонок на ${moved.h} строк`,
      );
    }
  };

  const resetLayout = () => {
    setLayout(DEFAULT_ITEMS);
    setAnnounce('Раскладка сброшена к исходной');
  };

  const toggleView = (id: string) => {
    setViews((prev) => ({ ...prev, [id]: prev[id] === 'table' ? 'chart' : 'table' }));
  };

  return (
    <div className="dash" data-theme={theme}>
      <header className="dash-head">
        <div className="dash-titles">
          <h1 className="dash-title">Обзор продаж</h1>
          <p className="dash-sub">
            {editing
              ? 'Перетаскивайте виджеты за ручку и меняйте размер за правый нижний угол. Клавиатура: фокус на ручку, затем стрелки.'
              : 'Нажмите «Редактировать», чтобы переставить виджеты.'}
          </p>
        </div>
        <div className="dash-tools">
          <SegmentedRadioGroup
            size="m"
            value={String(range)}
            onUpdate={(v: string) => setRange(Number(v) as RangeDays)}
            options={[
              { value: '7', content: '7 дн.' },
              { value: '30', content: '30 дн.' },
              { value: '90', content: '90 дн.' },
            ]}
          />
          <SegmentedRadioGroup
            size="m"
            value={theme}
            onUpdate={(v: string) => onThemeChange(v === 'dark' ? 'dark' : 'light')}
            options={[
              { value: 'light', content: 'Светлая' },
              { value: 'dark', content: 'Тёмная' },
            ]}
          />
          <Button view={editing ? 'action' : 'outlined'} size="m" onClick={() => setEditing((v) => !v)}>
            {editing ? 'Готово' : 'Редактировать'}
          </Button>
          {editing && (
            <Button view="flat" size="m" onClick={resetLayout}>
              Сбросить раскладку
            </Button>
          )}
        </div>
      </header>

      <div className="dash-grid" ref={gridRef} style={{ height: gridHeight }}>
        {colW > 0 &&
          WIDGETS.map((def) => {
            const it = items.find((x) => x.i === def.id);
            if (!it) return null;
            const rect = itemRectPx(it, colW);
            const view = views[def.id] ?? 'chart';
            const cls = ['dash-item', editing && 'is-editing', activeId === def.id && 'is-active']
              .filter(Boolean)
              .join(' ');
            return (
              <section
                key={def.id}
                className={cls}
                style={{ left: rect.left, top: rect.top, width: rect.width, height: rect.height }}
                aria-labelledby={`${def.id}-title`}
              >
                <header className="w-head">
                  <h2 id={`${def.id}-title`} className="w-title">
                    {def.title}
                  </h2>
                  <div className="w-tools">
                    {def.hasTable && (
                      <Button size="s" view="flat" onClick={() => toggleView(def.id)}>
                        {view === 'table' ? 'График' : 'Таблица'}
                      </Button>
                    )}
                    {editing && (
                      <button
                        type="button"
                        className="w-handle"
                        aria-label={`Переместить виджет «${def.title}»`}
                        onPointerDown={(e) => beginDrag(e, def.id, 'move')}
                        onPointerMove={onDragMove}
                        onPointerUp={(e) => endDrag(e, true)}
                        onPointerCancel={(e) => endDrag(e, false)}
                        onKeyDown={(e) => onHandleKey(e, def.id, 'move')}
                      >
                        <svg width="12" height="16" viewBox="0 0 12 16" aria-hidden="true">
                          {[3, 8, 13].map((cy) =>
                            [3, 9].map((cx) => <circle key={`${cx}-${cy}`} cx={cx} cy={cy} r={1.5} />),
                          )}
                        </svg>
                      </button>
                    )}
                  </div>
                </header>

                <div className="w-body">{def.render(data, view)}</div>

                {editing && (
                  <button
                    type="button"
                    className="w-resize"
                    aria-label={`Изменить размер виджета «${def.title}»`}
                    onPointerDown={(e) => beginDrag(e, def.id, 'resize')}
                    onPointerMove={onDragMove}
                    onPointerUp={(e) => endDrag(e, true)}
                    onPointerCancel={(e) => endDrag(e, false)}
                    onKeyDown={(e) => onHandleKey(e, def.id, 'resize')}
                  />
                )}
              </section>
            );
          })}
      </div>

      <div className="sr-only" aria-live="polite">
        {announce}
      </div>
      <p className="dash-foot">
        Сетка из {COLS} колонок. Раскладка сохраняется в этом браузере.
      </p>
    </div>
  );
}

args.content:
/* Dashboard styles. Colors are roles from the reference palette (light/dark). */

.dash {
  --page: #f9f9f7;
  --surface: #fcfcfb;
  --text: #0b0b0b;
  --text-2: #52514e;
  --muted: #898781;
  --grid: #e1e0d9;
  --baseline: #c3c2b7;
  --border: rgba(11, 11, 11, 0.1);
  --hover: rgba(11, 11, 11, 0.05);
  --tip-bg: #ffffff;
  --shadow: 0 6px 18px rgba(11, 11, 11, 0.12);

  /* Categorical slots, blue / orange / aqua / yellow (order is the CVD mechanism). */
  --s1: #2a78d6;
  --s2: #eb6834;
  --s3: #1baf7a;
  --s4: #eda100;
  --on-fill: #ffffff;
  --on-yellow: #0b0b0b;

  /* Status text for deltas: always paired with an arrow and a sign. */
  --good-text: #006300;
  --bad-text: #d03b3b;

  color-scheme: light;
  box-sizing: border-box;
  min-height: 100vh;
  padding: 24px 28px 32px;
  background: var(--page);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
}

.dash[data-theme='dark'] {
  --page: #0d0d0d;
  --surface: #1a1a19;
  --text: #f0efec;
  --text-2: #c3c2b7;
  --muted: #898781;
  --grid: #2c2c2a;
  --baseline: #383835;
  --border: rgba(255, 255, 255, 0.1);
  --hover: rgba(255, 255, 255, 0.06);
  --tip-bg: #2a2a28;
  --shadow: 0 6px 18px rgba(0, 0, 0, 0.45);

  --s1: #3987e5;
  --s2: #d95926;
  --s3: #199e70;
  --s4: #c98500;
  --on-fill: #ffffff;
  --on-yellow: #ffffff;

  --good-text: #0ca30c;
  --bad-text: #d03b3b;

  color-scheme: dark;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ---- Header ----------------------------------------------------------- */

.dash-head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 20px;
}

.dash-title {
  margin: 0;
  font-size: 22px;
  font-weight: 600;
}

.dash-sub {
  margin: 4px 0 0;
  font-size: 13px;
  color: var(--text-2);
  max-width: 640px;
}

.dash-tools {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.dash-foot {
  margin: 16px 0 0;
  font-size: 12px;
  color: var(--muted);
}

/* ---- Grid and widget frame ------------------------------------------- */

.dash-grid {
  position: relative;
  width: 100%;
}

.dash-item {
  position: absolute;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  padding: 14px 16px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  transition:
    left 0.18s ease,
    top 0.18s ease,
    width 0.18s ease,
    height 0.18s ease;
}

.dash-item.is-editing {
  border-color: var(--muted);
}

.dash-item.is-active {
  transition: none;
  z-index: 2;
  box-shadow: var(--shadow);
}

.w-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 28px;
  margin-bottom: 6px;
}

.w-title {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
}

.w-tools {
  display: flex;
  align-items: center;
  gap: 4px;
}

.w-body {
  position: relative;
  display: flex;
  flex: 1 1 0;
  flex-direction: column;
  min-height: 0;
}

.w-handle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--muted);
  cursor: grab;
  touch-action: none;
  user-select: none;
}

.w-handle svg circle {
  fill: currentColor;
}

.w-handle:hover {
  background: var(--hover);
  color: var(--text);
}

.w-handle:active {
  cursor: grabbing;
}

.w-resize {
  position: absolute;
  right: 4px;
  bottom: 4px;
  width: 16px;
  height: 16px;
  padding: 0;
  border: 0;
  background: linear-gradient(
    135deg,
    transparent 0 46%,
    var(--muted) 46% 54%,
    transparent 54% 70%,
    var(--muted) 70% 78%,
    transparent 78%
  );
  cursor: nwse-resize;
  touch-action: none;
}

.w-handle:focus-visible,
.w-resize:focus-visible {
  outline: 2px solid var(--s1);
  outline-offset: 2px;
}

/* ---- Stat tile -------------------------------------------------------- */

.kpi {
  display: flex;
  flex: 1 1 0;
  flex-direction: column;
  gap: 6px;
  min-height: 0;
}

.kpi-value {
  font-size: 30px;
  font-weight: 600;
  line-height: 1.1;
  color: var(--text);
}

.kpi-hero {
  font-size: 48px;
}

.kpi-delta-row {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 8px;
  font-size: 12px;
}

.kpi-delta {
  font-weight: 600;
}

.kpi-up {
  color: var(--good-text);
}

.kpi-down {
  color: var(--bad-text);
}

.kpi-flat {
  color: var(--text-2);
}

.kpi-vs {
  color: var(--muted);
}

.spark {
  display: block;
  width: 100%;
  height: 32px;
  margin-top: auto;
  overflow: visible;
}

.spark-line {
  stroke: var(--muted);
  stroke-width: 1.5;
}

.spark-dot {
  fill: var(--s1);
  stroke: var(--surface);
  stroke-width: 2;
}

/* ---- Line chart ------------------------------------------------------- */

.line-chart {
  position: relative;
  flex: 1 1 0;
  min-height: 0;
  width: 100%;
}

.lc-svg {
  position: absolute;
  top: 0;
  left: 0;
  display: block;
  overflow: visible;
  outline: none;
}

.lc-svg:focus-visible {
  box-shadow: 0 0 0 2px var(--s1);
  border-radius: 6px;
}

.lc-grid,
.lc-base,
.lc-cross {
  stroke: var(--grid);
  stroke-width: 1;
}

.lc-base {
  stroke: var(--baseline);
}

.lc-cross {
  stroke: var(--baseline);
}

.lc-tick {
  font-size: 11px;
  fill: var(--muted);
}

.lc-end {
  font-size: 12px;
  fill: var(--text-2);
  font-variant-numeric: tabular-nums;
}

.lc-line {
  fill: none;
  stroke-width: 2;
  stroke-linejoin: round;
  stroke-linecap: round;
}

.lc-dot {
  stroke: var(--surface);
  stroke-width: 2;
}

.lc-tip {
  display: block;
}

/* ---- Legend ----------------------------------------------------------- */

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  margin: 0 0 6px;
  padding: 0;
  list-style: none;
  font-size: 12px;
  color: var(--text-2);
}

.legend li {
  display: flex;
  align-items: center;
  gap: 6px;
}

.legend-key {
  display: inline-block;
  flex: none;
}

.legend-key-line {
  width: 12px;
  height: 2px;
  border-radius: 1px;
}

.legend-key-box {
  width: 10px;
  height: 10px;
  border-radius: 2px;
}

/* ---- Tooltips --------------------------------------------------------- */

.tip {
  position: absolute;
  z-index: 5;
  box-sizing: border-box;
  min-width: 150px;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--tip-bg);
  box-shadow: var(--shadow);
  font-size: 12px;
  color: var(--text-2);
  pointer-events: none;
  white-space: nowrap;
}

.tip-title,
.tip-name {
  display: block;
  color: var(--text-2);
}

.tip-title {
  margin-bottom: 4px;
}

.tip-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 2px 0;
}

.tip-key {
  flex: none;
}

.tip-key-line {
  width: 12px;
  height: 2px;
  border-radius: 1px;
}

.tip-name {
  flex: 1;
}

.tip-value {
  margin-left: auto;
  font-size: 13px;
  font-weight: 600;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

.rb-tip,
.seg-tip {
  display: none;
}

/* ---- Ranked bars ------------------------------------------------------ */

.rb {
  display: flex;
  flex: 1 1 0;
  flex-direction: column;
  justify-content: space-around;
  gap: 4px;
  min-height: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}

.rb-row {
  position: relative;
  display: grid;
  grid-template-columns: 118px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  min-height: 30px;
  padding: 0 6px;
  border-radius: 6px;
  outline: none;
}

.rb-row:hover,
.rb-row:focus-visible {
  background: var(--hover);
}

.rb-row:focus-visible {
  box-shadow: 0 0 0 2px var(--s1);
}

.rb-row:hover .rb-tip,
.rb-row:focus-visible .rb-tip {
  display: block;
}

.rb-tip {
  top: 100%;
  right: 6px;
  margin-top: 2px;
}

.rb-name {
  overflow: hidden;
  font-size: 12px;
  color: var(--text-2);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rb-track {
  position: relative;
  display: block;
  height: 18px;
}

.rb-fill {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  min-width: 2px;
  border-radius: 0 4px 4px 0;
  background: var(--s1);
}

.rb-value {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  font-size: 12px;
  color: var(--text);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

/* ---- Segmented bar ---------------------------------------------------- */

.seg-wrap {
  display: flex;
  flex: 1 1 0;
  flex-direction: column;
  justify-content: center;
  gap: 12px;
  min-height: 0;
}

.seg {
  display: flex;
  gap: 2px;
  height: 28px;
}

.seg-part {
  position: relative;
  display: flex;
  align-items: center;
  min-width: 0;
  padding: 0 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  outline: none;
}

.seg-part:hover {
  filter: brightness(1.08);
}

.seg-part:focus-visible {
  box-shadow:
    0 0 0 2px var(--surface),
    0 0 0 4px var(--s1);
}

.seg-part:hover .seg-tip,
.seg-part:focus-visible .seg-tip {
  display: block;
}

.seg-tip {
  bottom: calc(100% + 6px);
  left: 0;
  color-scheme: inherit;
}

.seg-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 18px;
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 12px;
  color: var(--text-2);
}

.seg-legend li {
  display: flex;
  align-items: center;
  gap: 6px;
}

/* ---- Table view ------------------------------------------------------- */

.dt-scroll {
  flex: 1 1 0;
  min-height: 0;
  overflow: auto;
}

.dt {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
  color: var(--text-2);
}

.dt th,
.dt td {
  padding: 6px 8px;
  border-bottom: 1px solid var(--grid);
  text-align: left;
}

.dt th {
  position: sticky;
  top: 0;
  background: var(--surface);
  font-weight: 500;
  color: var(--muted);
}

.dt .num {
  text-align: right;
  font-variant-numeric: tabular-nums;
  color: var(--text);
}

