}

.dash-sub {
  margin: 4px 0 0;
  font-size: 13px;
  color: var(--text-2);
  max-width: 640px;
}

.dash-tools {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.dash-foot {
  margin: 16px 0 0;
  font-size: 12px;
  color: var(--muted);
}

/* ---- Grid and widget frame ------------------------------------------- */

.dash-grid {
  position: relative;
  width: 100%;
}

.dash-item {
  position: absolute;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  padding: 14px 16px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  transition:
    left 0.18s ease,
    top 0.18s ease,
    width 0.18s ease,
    height 0.18s ease;
}

.dash-item.is-editing {
  border-color: var(--muted);
}

.dash-item.is-active {
  transition: none;
  z-index: 2;
  box-shadow: var(--shadow);
}

.w-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 28px;
  margin-bottom: 6px;
}

.w-title {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
}

.w-tools {
  display: flex;
  align-items: center;
  gap: 4px;
}

.w-body {
  position: relative;
  display: flex;
  flex: 1 1 0;
  flex-direction: column;
  min-height: 0;
}

.w-handle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--muted);
  cursor: grab;
  touch-action: none;
  user-select: none;
}

.w-handle svg circle {
  fill: currentColor;
}

.w-handle:hover {
  background: var(--hover);
  color: var(--text);
}

.w-handle:active {
  cursor: grabbing;
}

.w-resize {
  position: absolute;
  right: 4px;
  bottom: 4px;
  width: 16px;
  height: 16px;
  padding: 0;
  border: 0;
  background: linear-gradient(
    135deg,
    transparent 0 46%,
    var(--muted) 46% 54%,
    transparent 54% 70%,
    var(--muted) 70% 78%,
    transparent 78%
  );
  cursor: nwse-resize;
  touch-action: none;
}

.w-handle:focus-visible,
.w-resize:focus-visible {
  outline: 2px solid var(--s1);
  outline-offset: 2px;
}

/* ---- Stat tile -------------------------------------------------------- */

.kpi {
  display: flex;
  flex: 1 1 0;
  flex-direction: column;
  gap: 6px;
  min-height: 0;
}

.kpi-value {
  font-size: 30px;
  font-weight: 600;
  line-height: 1.1;
  color: var(--text);
}

.kpi-hero {
  font-size: 48px;
}

.kpi-delta-row {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 8px;
  font-size: 12px;
}

.kpi-delta {
  font-weight: 600;
}

.kpi-up {
  color: var(--good-text);
}

.kpi-down {
  color: var(--bad-text);
}

.kpi-flat {
  color: var(--text-2);
}

.kpi-vs {
  color: var(--muted);
}

.spark {
  display: block;
  width: 100%;
  height: 32px;
  margin-top: auto;
  overflow: visible;
}

.spark-line {
  stroke: var(--muted);
  stroke-width: 1.5;
}

.spark-dot {
  fill: var(--s1);
  stroke: var(--surface);
  stroke-width: 2;
}

/* ---- Line chart ------------------------------------------------------- */

.line-chart {
  position: relative;
  flex: 1 1 0;
  min-height: 0;
  width: 100%;
}

.lc-svg {
  position: absolute;
  top: 0;
  left: 0;
  display: block;
  overflow: visible;
  outline: none;
}

.lc-svg:focus-visible {
  box-shadow: 0 0 0 2px var(--s1);
  border-radius: 6px;
}

.lc-grid,
.lc-base,
.lc-cross {
  stroke: var(--grid);
  stroke-width: 1;
}

.lc-base {
  stroke: var(--baseline);
}

.lc-cross {
  stroke: var(--baseline);
}

.lc-tick {
  font-size: 11px;
  fill: var(--muted);
}

.lc-end {
  font-size: 12px;
  fill: var(--text-2);
  font-variant-numeric: tabular-nums;
}

.lc-line {
  fill: none;
  stroke-width: 2;
  stroke-linejoin: round;
  stroke-linecap: round;
}

.lc-dot {
  stroke: var(--surface);
  stroke-width: 2;
}

.lc-tip {
  display: block;
}

/* ---- Legend ----------------------------------------------------------- */

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  margin: 0 0 6px;
  padding: 0;
  list-style: none;
  font-size: 12px;
  color: var(--text-2);
}

.legend li {
  display: flex;
  align-items: center;
  gap: 6px;
}

.legend-key {
  display: inline-block;
  flex: none;
}

.legend-key-line {
  width: 12px;
  height: 2px;
  border-radius: 1px;
}

.legend-key-box {
  width: 10px;
  height: 10px;
  border-radius: 2px;
}

/* ---- Tooltips --------------------------------------------------------- */

.tip {
  position: absolute;
  z-index: 5;
  box-sizing: border-box;
  min-width: 150px;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--tip-bg);
  box-shadow: var(--shadow);
  font-size: 12px;
  color: var(--text-2);
  pointer-events: none;
  white-space: nowrap;
}

.tip-title,
.tip-name {
  display: block;
  color: var(--text-2);
}

.tip-title {
  margin-bottom: 4px;
}

.tip-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 2px 0;
}

.tip-key {
  flex: none;
}

.tip-key-line {
  width: 12px;
  height: 2px;
  border-radius: 1px;
}

.tip-name {
  flex: 1;
}

.tip-value {
  margin-left: auto;
  font-size: 13px;
  font-weight: 600;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

.rb-tip,
.seg-tip {
  display: none;
}

/* ---- Ranked bars ------------------------------------------------------ */

.rb {
  display: flex;
  flex: 1 1 0;
  flex-direction: column;
  justify-content: space-around;
  gap: 4px;
  min-height: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}

.rb-row {
  position: relative;
  display: grid;
  grid-template-columns: 118px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  min-height: 30px;
  padding: 0 6px;
  border-radius: 6px;
  outline: none;
}

.rb-row:hover,
.rb-row:focus-visible {
  background: var(--hover);
}

.rb-row:focus-visible {
  box-shadow: 0 0 0 2px var(--s1);
}

.rb-row:hover .rb-tip,
.rb-row:focus-visible .rb-tip {
  display: block;
}

.rb-tip {
  top: 100%;
  right: 6px;
  margin-top: 2px;
}

.rb-name {
  overflow: hidden;
  font-size: 12px;
  color: var(--text-2);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rb-track {
  position: relative;
  display: block;
  height: 18px;
}

.rb-fill {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  min-width: 2px;
  border-radius: 0 4px 4px 0;
  background: var(--s1);
}

.rb-value {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  font-size: 12px;
  color: var(--text);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

/* ---- Segmented bar ---------------------------------------------------- */

.seg-wrap {
  display: flex;
  flex: 1 1 0;
  flex-direction: column;
  justify-content: center;
  gap: 12px;
  min-height: 0;
}

.seg {
  display: flex;
  gap: 2px;
  height: 28px;
}

.seg-part {
  position: relative;
  display: flex;
  align-items: center;
  min-width: 0;
  padding: 0 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  outline: none;
}

.seg-part:hover {
  filter: brightness(1.08);
}

.seg-part:focus-visible {
  box-shadow:
    0 0 0 2px var(--surface),
    0 0 0 4px var(--s1);
}

.seg-part:hover .seg-tip,
.seg-part:focus-visible .seg-tip {
  display: block;
}

.seg-tip {
  bottom: calc(100% + 6px);
  left: 0;
  color-scheme: inherit;
}

.seg-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 18px;
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 12px;
  color: var(--text-2);
}

.seg-legend li {
  display: flex;
  align-items: center;
  gap: 6px;
}

/* ---- Table view ------------------------------------------------------- */

.dt-scroll {
  flex: 1 1 0;
  min-height: 0;
  overflow: auto;
}

.dt {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
  color: var(--text-2);
}

.dt th,
.dt td {
  padding: 6px 8px;
  border-bottom: 1px solid var(--grid);
  text-align: left;
}

.dt th {
  position: sticky;
  top: 0;
  background: var(--surface);
  font-weight: 500;
  color: var(--muted);
}

.dt .num {
  text-align: right;
  font-variant-numeric: tabular-nums;
  color: var(--text);
}

