args.content:
import { chromium } from 'playwright';

const URL = 'http://127.0.0.1:5173/';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 1000 }, deviceScaleFactor: 1 });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`[${m.type()}] ${m.text()}`); });
page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message}`));

await page.goto(URL, { waitUntil: 'networkidle' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'networkidle' });
await page.waitForSelector('.dash-item');
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/shot/01-light.png', fullPage: true });

// Dark theme
await page.getByText('Тёмная', { exact: true }).click();
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/shot/02-dark.png', fullPage: true });
await page.getByText('Светлая', { exact: true }).click();
await page.waitForTimeout(200);

// Hover a line-chart point and a ranked bar row
const svg = page.locator('.lc-svg');
const box = await svg.boundingBox();
await page.mouse.move(box.x + box.width * 0.6, box.y + box.height * 0.5);
await page.waitForTimeout(200);
await page.screenshot({ path: '/tmp/shot/03-hover-line.png', fullPage: true });

await page.locator('.rb-row').nth(1).hover();
await page.waitForTimeout(200);
await page.screenshot({ path: '/tmp/shot/04-hover-bar.png', fullPage: true });

// Table view on the line chart
await page.locator('.dash-item', { has: page.locator('.w-title', { hasText: 'Заказы по каналам' }) }).getByRole('button', { name: 'Таблица' }).click();
await page.waitForTimeout(200);
await page.screenshot({ path: '/tmp/shot/05-table.png', fullPage: true });

console.log(JSON.stringify(errors, null, 2));
await browser.close();

