const b = await chromium.launch({ args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage', '--use-gl=swiftshader'] });
const p = await b.newPage();
p.on('console', m => console.log('console:', m.type(), m.text().slice(0,200)));
p.on('crash', () => console.log('PAGE CRASHED'));
await p.goto('http://127.0.0.1:5173/', { waitUntil: 'load', timeout: 60000 });
console.log('title:', await p.title());
await p.waitForTimeout(1500);
console.log('items:', await p.locator('.dash-item').count());
await b.close();
EOF
