args.content:
import { chromium } from 'playwright';

const URL = 'http://127.0.0.1:5173/';
const browser = await chromium.launch({ args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
await page.route('**/*', (r) => (r.request().url().startsWith('http://127.0.0.1') ? r.continue() : r.abort()));
const errors = [];
page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
page.on('console', (m) => { if (m.type() === 'error' && !m.text().includes('ERR_FAILED')) errors.push(`console: ${m.text()}`); });

const fail = (msg) => { console.log('FAIL:', msg); process.exitCode = 1; };
const pass = (msg) => console.log('ok  :', msg);

// Read every widget's grid cell back from the DOM, using the grid's own maths.
async function readCells() {
  return page.evaluate(() => {
    const grid = document.querySelector('.dash-grid');
    const gw = grid.getBoundingClientRect().width;
    const colW = (gw - 16 * 11) / 12;
    const stepX = colW + 16;
    const stepY = 80 + 16;
    return [...document.querySelectorAll('.dash-item')].map((el) => {
      const title = el.querySelector('.w-title').textContent;
      const left = parseFloat(el.style.left);
      const top = parseFloat(el.style.top);
      const width = parseFloat(el.style.width);
      const height = parseFloat(el.style.height);
      return {
        title,
        x: Math.round(left / stepX),
        y: Math.round(top / stepY),
        w: Math.round((width + 16) / stepX),
        h: Math.round((height + 16) / stepY),
      };
    });
  });
}

const overlapFree = (cells) => {
  for (let a = 0; a < cells.length; a++) for (let b = a + 1; b < cells.length; b++) {
    const A = cells[a], B = cells[b];
    if (A.x < B.x + B.w && B.x < A.x + A.w && A.y < B.y + B.h && B.y < A.y + A.h) return `${A.title} overlaps ${B.title}`;
  }
  for (const c of cells) if (c.x < 0 || c.x + c.w > 12 || c.y < 0) return `${c.title} out of bounds`;
  return null;
};

const byTitle = (cells, t) => cells.find((c) => c.title === t);

await page.goto(URL, { waitUntil: 'load' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'load' });
await page.waitForSelector('.dash-item');

let cells = await readCells();
const initial = JSON.stringify(cells);
overlapFree(cells) ? fail('initial overlap') : pass('default layout is overlap-free and in bounds');

await page.getByRole('button', { name: 'Редактировать' }).click();
await page.waitForSelector('.w-handle');
pass('edit mode shows drag handles');

// --- 1. Drag the revenue tile (x0,y0) onto the chart area (x8,y2).
const gridBox = await page.locator('.dash-grid').boundingBox();
const colW = (gridBox.width - 16 * 11) / 12;
const handle = page.locator('.dash-item', { hasText: 'Выручка' }).first().locator('.w-handle');
const hb = await handle.boundingBox();
const sx = hb.x + hb.width / 2, sy = hb.y + hb.height / 2;
await page.mouse.move(sx, sy);
await page.mouse.down();
const tx = sx + 8 * (colW + 16), ty = sy + 2 * 96;
for (let s = 1; s <= 12; s++) {
  await page.mouse.move(sx + ((tx - sx) * s) / 12, sy + ((ty - sy) * s) / 12);
}
await page.mouse.up();
await page.waitForTimeout(300);
cells = await readCells();
const err1 = overlapFree(cells);
err1 ? fail(`after drag: ${err1}`) : pass('drag: no overlaps after pushing items');
const rev = byTitle(cells, 'Выручка');
const reg = byTitle(cells, 'Выручка по регионам');
console.log('      revenue now at', rev.x, rev.y, 'regions at', reg.x, reg.y, reg.w, reg.h);
if (rev.x !== 8) fail(`expected revenue x=8, got ${rev.x}`); else pass('drag: tile snapped to target column');
if (JSON.stringify(cells) === initial) fail('drag changed nothing'); else pass('drag: layout changed');

// --- 2. Resize the traffic bar from its corner: width 12 -> 9.
const rh = page.locator('.dash-item', { hasText: 'Источники трафика' }).first().locator('.w-resize');
const rb = await rh.boundingBox();
const rx = rb.x + rb.width / 2, ry = rb.y + rb.height / 2;
await page.mouse.move(rx, ry);
await page.mouse.down();
for (let s = 1; s <= 8; s++) await page.mouse.move(rx - (3 * (colW + 16) * s) / 8, ry);
await page.mouse.up();
await page.waitForTimeout(300);
cells = await readCells();
overlapFree(cells) ? fail('after resize: overlap') : pass('resize: no overlaps');
const tr = byTitle(cells, 'Источники трафика');
tr.w === 9 ? pass(`resize: traffic width is ${tr.w}`) : fail(`traffic width expected 9, got ${tr.w}`);

// --- 3. Keyboard: focus the regions handle, move it one column right.
const before = byTitle(await readCells(), 'Выручка по регионам');
await page.locator('.dash-item', { hasText: 'Выручка по регионам' }).first().locator('.w-handle').focus();
await page.keyboard.press('ArrowRight');
await page.waitForTimeout(250);
cells = await readCells();
const after = byTitle(cells, 'Выручка по регионам');
overlapFree(cells) ? fail('keyboard: overlap') : pass('keyboard: no overlaps');
(after.x === Math.min(before.x + 1, 12 - after.w) || after.x === before.x + 1) ? pass(`keyboard: regions moved ${before.x} -> ${after.x}`) : fail(`keyboard move unexpected ${before.x} -> ${after.x}`);

// --- 4. Persistence: reload keeps the custom layout.
const saved = await page.evaluate(() => localStorage.getItem('viz-dashboard-layout:v1'));
saved ? pass('layout persisted to localStorage') : fail('nothing persisted');
const layoutBeforeReload = JSON.stringify(await readCells());
await page.reload({ waitUntil: 'load' });
await page.waitForSelector('.dash-item');
const layoutAfterReload = JSON.stringify(await readCells());
layoutBeforeReload === layoutAfterReload ? pass('layout survives reload') : fail('layout changed on reload');

// --- 5. Corrupt storage falls back to defaults without crashing.
await page.evaluate(() => localStorage.setItem('viz-dashboard-layout:v1', '{"broken":true}'));
await page.reload({ waitUntil: 'load' });
await page.waitForSelector('.dash-item');
JSON.stringify(await readCells()) === initial ? pass('corrupt storage falls back to default layout') : fail('corrupt storage not handled');

// --- 6. Edit, then reset restores defaults.
await page.getByRole('button', { name: 'Редактировать' }).click();
await page.getByRole('button', { name: 'Сбросить раскладку' }).click();
await page.waitForTimeout(250);
JSON.stringify(await readCells()) === initial ? pass('reset restores default layout') : fail('reset did not restore');

// --- 7. Table toggle still works in the resized layout and stays inside its card.
await page.getByRole('button', { name: 'Редактировать' }).click();
const tBtn = page.locator('.dash-item', { hasText: 'Заказы по каналам' }).first().getByRole('button', { name: 'Таблица' });
await tBtn.click();
await page.waitForTimeout(200);
const overflow = await page.evaluate(() => {
  const item = [...document.querySelectorAll('.dash-item')].find((el) => el.textContent.includes('Заказы по каналам'));
  const scroller = item.querySelector('.dt-scroll');
  return { itemH: item.getBoundingClientRect().height, scrollerH: scroller.getBoundingClientRect().height, itemBottom: item.getBoundingClientRect().bottom, scrollerBottom: scroller.getBoundingClientRect().bottom };
});
overflow.scrollerBottom <= overflow.itemBottom + 1 ? pass('table view stays inside its card') : fail(`table overflows card ${JSON.stringify(overflow)}`);

await page.locator('.dash').screenshot({ path: '/tmp/shot/06-edit-table.png' });
await page.getByRole('button', { name: 'Таблица' }).first().click().catch(() => {});

// Screenshot of an edited layout (fresh state with a drag applied).
await page.getByRole('button', { name: 'Готово' }).click();
await page.waitForTimeout(200);
await page.screenshot({ path: '/tmp/shot/07-after-edit.png', fullPage: true });

console.log(errors.length ? `ERRORS:\n${errors.join('\n')}` : 'no runtime errors');
await browser.close();

